import React, { useEffect, useState, useMemo } from "react";
import { fetchUsers } from "../api/userServices";
import { deriveStatus } from "../../shared/types";

import { GrowthChart } from "../components/charts/GrowthChart";
import { DonutChart } from "../nutChart";
import { TopListBar } from "../components/charts/TopListBar";

type GrowthPeriod = "days" | "weeks" | "months";

interface AppUser {
  id: string;
  name: string;
  email?: string | null;
  phone?: string | null;
  created_at?: string | null;
  updated_at?: string | null;
  user_type_names?: string[];
  location?: string;
  location_names?: string[];
  skills_id?: string[];
  is_active?: boolean | null;
  status?: "active" | "pending" | "suspended" | "dormant";
}

// ── same helper (keep yours)
function buildGrowthBuckets(users: AppUser[], period: GrowthPeriod) {
  const now = new Date();

  if (period === "days") {
    return Array.from({ length: 14 }, (_, i) => {
      const d = new Date(now);
      d.setDate(d.getDate() - (13 - i));
      return {
        label: d.toDateString().slice(0, 10),
        clients: 0,
        freelancers: 0,
      };
    });
  }

  if (period === "weeks") {
    return Array.from({ length: 8 }, (_, i) => ({
      label: `W${i + 1}`,
      clients: 0,
      freelancers: 0,
    }));
  }

  return Array.from({ length: 6 }, (_, i) => ({
    label: `M${i + 1}`,
    clients: 0,
    freelancers: 0,
  }));
}

const UserAnalytics: React.FC = () => {
  const [users, setUsers] = useState<AppUser[]>([]);
  const [loading, setLoading] = useState(true);

  // ✅ FIXED: setPeriod now actually used
  const [period, setPeriod] = useState<GrowthPeriod>("months");

  useEffect(() => {
    fetchUsers()
      .then(setUsers)
      .finally(() => setLoading(false));
  }, []);

  // 🔥 REALTIME POLLING (upgradeable to Supabase later)
  useEffect(() => {
    const interval = setInterval(async () => {
      const fresh = await fetchUsers();
      setUsers(fresh);
    }, 15000);

    return () => clearInterval(interval);
  }, []);

  const stats = useMemo(() => {
    let clients = 0;
    let freelancers = 0;
    let suspended = 0;

    const locationMap: Record<string, number> = {};
    const skillMap: Record<string, number> = {};

    users.forEach((u) => {
      const status = deriveStatus(u as any);

      if (status === "suspended") suspended++;
      else {
        const types = u.user_type_names ?? [];
        if (types.includes("hire talent")) clients++;
        if (types.includes("find work")) freelancers++;
      }

      (u.location_names ?? [u.location].filter(Boolean)).forEach((l) => {
        if (l) locationMap[l] = (locationMap[l] || 0) + 1;
      });

      (u.skills_id ?? []).forEach((skill: string) => {
        if (skill) skillMap[skill] = (skillMap[skill] || 0) + 1;
      });
    });

    return {
      total: users.length,
      clients,
      freelancers,
      suspended,
      topLocations: Object.entries(locationMap)
        .map(([name, count]) => ({ name, count }))
        .slice(0, 5),

      topSkills: Object.entries(skillMap)
        .map(([name, count]) => ({ name, count }))
        .slice(0, 5),
    };
  }, [users]);

  const growthData = useMemo(
    () => buildGrowthBuckets(users, period),
    [users, period]
  );

  if (loading) return <div>Loading...</div>;

  return (
    <div style={{ padding: 20, fontFamily: "DM Sans" }}>
      <h2>User Analytics</h2>

      {/* PERIOD SELECTOR */}
      <select value={period} onChange={(e) => setPeriod(e.target.value as GrowthPeriod)}>
        <option value="days">Days</option>
        <option value="weeks">Weeks</option>
        <option value="months">Months</option>
      </select>

      {/* STATS */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 12 }}>
        <div>Total: {stats.total}</div>
        <div>Clients: {stats.clients}</div>
        <div>Freelancers: {stats.freelancers}</div>
        <div>Suspended: {stats.suspended}</div>
      </div>

      {/* CHARTS */}
      <div style={{ marginTop: 20 }}>
        <GrowthChart data={growthData} />
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 20 }}>
        <DonutChart
          clients={stats.clients}
          freelancers={stats.freelancers}
          suspended={stats.suspended}
        />

        <div>
          <h4>Top Skills</h4>
          <TopListBar items={stats.topSkills} color="#0F172A" />
        </div>
      </div>

      <div style={{ marginTop: 20 }}>
        <h4>Top Locations</h4>
        <TopListBar items={stats.topLocations} color="#EA580C" />
      </div>
    </div>
  );
};

export default UserAnalytics;
